def solve_for_n(n, max_k=20):
    R = [0] * (max_k + 1)
    R[1] = 1**n
    for k in range(2, max_k + 1):
        R[k] = k * R[k-1] + k**n

    possible = True
    for k in range(2, max_k + 1):
        fact_k_minus_1 = 1
        for i in range(1, k):
            fact_k_minus_1 *= i
        if R[k] % fact_k_minus_1 != R[k-1] % fact_k_minus_1:
            possible = False
            break

    if possible:
        print(f"n={n} is possible")
    else:
        print(f"n={n} is not possible")

